insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(4286, '마사 브루타', '{브라간사 파울리스타,나비 아비 셰지드 경기장,1928년 창단}', $t$<p>RB 브라간치누는 상파울루주 내륙 도시 브라간사 파울리스타를 연고로 하는 구단입니다. 오랫동안 브라간치누라는 이름의 지역 구단이었지만, 2019년 레드불 그룹과 손잡은 뒤 지금의 이름으로 바뀌며 브라질에서 보기 드문 기업형 구단이 됐습니다. 같은 해 2부 리그 우승으로 1부에 올라왔고, 2021년에는 코파 수다메리카나 결승까지 진출했습니다. 젊은 선수를 키워 유럽으로 보내는 레드불 특유의 운영 방식이 그대로 적용되는 팀입니다.</p><p>토리코리 관전 포인트: 작은 홈구장에서 강한 압박을 거는 팀이라 홈 경기당 승점과 원정 경기당 승점의 차이를 먼저 확인해 보세요. 젊은 선수 위주라 경기력의 기복이 있는 편이니, 최근 5경기 흐름을 함께 보는 것이 좋습니다.</p>$t$),
(1767, '이모르타우', '{포르투알레그리,아레나 두 그레미우,1903년 창단}', $t$<p>그레미우는 브라질 최남단 히우그란지두술주의 주도 포르투알레그리를 대표하는 구단입니다. "불멸의 삼색군단"이라는 뜻의 별명처럼 끈질긴 승부로 유명하며, 코파 리베르타도레스를 1983년, 1995년, 2017년 세 차례 차지했습니다. 1983년에는 인터콘티넨털컵에서 함부르크를 꺾고 세계 정상에 올랐고, 호나우지뉴가 이 구단 유소년팀 출신입니다. 같은 도시의 인테르나시오나우와 치르는 그레나우 더비는 브라질에서 가장 격렬한 라이벌전 가운데 하나입니다.</p><p>토리코리 관전 포인트: 그레미우는 홈에서 강하고 원정에서 실리를 챙기는 경기가 많아 홈·원정 경기당 승점을 나눠 보는 것이 중요합니다. 거친 몸싸움이 많은 남부 축구 특성상 2.5골 언더로 끝나는 경기 비율도 함께 살펴보세요.</p>$t$),
(4364, '레앙', '{미하솔,조제 마리아 지 캄푸스 마이아 경기장,1925년 창단}', $t$<p>미하솔은 상파울루주 북서부의 작은 도시 미하솔을 연고로 하는 구단입니다. 노란색과 초록색 유니폼을 입고 "사자"라는 별명으로 불리며, 오랫동안 상파울루 주 리그와 하위 전국리그에서 활동해 왔습니다. 2024년 2부 리그에서 승격권에 들며 창단 이후 처음으로 브라질 1부 리그 무대를 밟았습니다. 대도시 명문 구단들 사이에서 조직력으로 승부하는 지방 구단의 대표적인 사례로 꼽힙니다.</p><p>토리코리 관전 포인트: 1부 경험이 짧은 팀은 강팀과 약팀을 상대할 때 결과 차이가 크게 나는 경우가 많으니, 경기당 승점과 함께 무실점 비율을 확인해 보세요. 전반 실점이 적고 후반에 버티는 힘이 어떤지 전반·후반 득실점 지표로 비교하면 팀의 색깔이 잘 드러납니다.</p>$t$),
(1780, '크루스말치누', '{리우데자네이루,상자누아리우,1898년 창단}', $t$<p>바스쿠 다 가마는 리우데자네이루에서 포르투갈 이민자들이 만든 조정 클럽에서 출발한 구단입니다. 1920년대 흑인과 노동자 출신 선수를 적극적으로 기용하며 브라질 축구의 인종 차별에 맞선 구단으로 역사에 이름을 남겼습니다. 1998년 코파 리베르타도레스 우승을 차지했고, 호베르투 지나미치, 호마리우, 에드문두 같은 공격수들이 이 팀의 상징입니다. 플라멩구와 맞붙는 경기는 "백만 관중의 더비"라 불리는 리우의 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 바스쿠는 홈구장 상자누아리우의 열기가 대단해 홈 경기당 승점이 원정보다 눈에 띄게 높은 시즌이 많습니다. 기복이 큰 팀이므로 최근 5경기 결과와 양팀 득점 비율을 함께 보면 흐름을 읽기 쉽습니다.</p>$t$),
(1777, '이스콰드랑', '{사우바도르,아레나 폰치 노바,1931년 창단}', $t$<p>바이아는 브라질 북동부 바이아주의 주도 사우바도르를 연고로 하는 구단입니다. 1959년 처음 열린 전국 대회 타사 브라질에서 펠레가 뛰던 산투스를 꺾고 우승해 브라질 최초의 전국 챔피언이 됐고, 1988년에도 전국리그 정상에 올랐습니다. 파란색·빨간색·흰색의 삼색 유니폼으로 북동부에서 가장 많은 팬을 거느린 구단 가운데 하나입니다. 같은 도시의 비토리아와 치르는 바비 더비는 북동부 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 북동부의 무더운 날씨 속 홈 경기에서 바이아는 강한 모습을 보이는 경우가 많아 홈·원정 경기당 승점을 나눠 보는 것이 좋습니다. 브라질 리그는 한 해 안에 시즌이 시작하고 끝나는 만큼, 시즌 후반부로 갈수록 체력 부담이 후반 실점에 어떻게 나타나는지도 확인해 보세요.</p>$t$),
(1770, '글로리오주', '{리우데자네이루,니우통 산투스 경기장,1904년 창단}', $t$<p>보타포구는 리우데자네이루의 보타포구 지역을 연고로 하는 구단으로, 1904년 창단한 축구 클럽과 1894년 출발한 조정 클럽이 1942년 합쳐져 지금의 모습이 됐습니다. 검은색과 흰색 유니폼에 "외로운 별" 엠블럼을 단 이 팀에서 가힌샤, 니우통 산투스, 지지, 자이르지뉴 같은 브라질 축구의 전설들이 뛰었습니다. 2024년에는 코파 리베르타도레스와 브라질 전국리그를 함께 차지하며 새 전성기를 열었습니다. 플라멩구, 플루미넨시, 바스쿠와 함께 리우의 4대 명문으로 꼽힙니다.</p><p>토리코리 관전 포인트: 보타포구는 공격 전개가 빠른 경기가 많아 2.5골 오버 비율과 양팀 득점 비율을 함께 보면 경기 성향을 파악하기 좋습니다. 무실점 비율이 높게 유지되는 시기에 성적도 함께 올라갔는지 팀 분석에서 비교해 보세요.</p>$t$),
(1782, '레앙 다 바하', '{사우바도르,바하당,1899년 창단}', $t$<p>비토리아는 사우바도르를 연고로 하는 구단으로, 1899년 창단해 브라질 북동부에서 가장 오래된 축구 구단 가운데 하나입니다. 빨간색과 검은색 유니폼을 입고 "바하의 사자"라는 별명으로 불리며, 1993년 브라질 전국리그 준우승이 대표적인 성과입니다. 베베투, 다비드 루이스, 헐크처럼 브라질 대표팀에서 활약한 선수들을 길러 낸 유소년 육성으로도 이름이 높습니다. 같은 도시의 바이아와 치르는 바비 더비는 사우바도르를 둘로 나누는 경기입니다.</p><p>토리코리 관전 포인트: 승격과 강등을 오가는 시기가 잦았던 팀이라 경기당 승점이 잔류권 기준에 얼마나 가까운지가 가장 중요한 지표입니다. 홈구장 바하당에서의 성적과 원정 성적의 차이를 홈·원정 경기당 승점으로 비교해 보세요.</p>$t$),
(6685, '페이시', '{산투스,빌라 베우미루,1912년 창단}', $t$<p>산투스는 상파울루주의 항구 도시 산투스를 연고로 하는 구단으로, "축구 황제" 펠레가 전성기를 보낸 팀으로 세계적으로 유명합니다. 펠레와 함께 1962년과 1963년 코파 리베르타도레스와 인터콘티넨털컵을 연달아 차지했고, 2011년에는 네이마르를 앞세워 세 번째 리베르타도레스 우승을 이뤘습니다. 2023년 창단 후 처음으로 2부로 강등되는 아픔을 겪었지만, 이듬해 2부 우승으로 곧바로 돌아왔습니다. 코린치앙스, 상파울루, 팔메이라스와 함께 상파울루주의 4대 명문으로 꼽힙니다.</p><p>토리코리 관전 포인트: 산투스는 전통적으로 공격적인 축구를 추구해 경기당 득점과 2.5골 오버 비율이 팀의 컨디션을 잘 보여 줍니다. 작은 홈구장 빌라 베우미루에서의 홈 경기당 승점이 원정보다 얼마나 높은지도 함께 확인해 보세요.</p>$t$),
(1776, '트리콜로르', '{상파울루,모룸비,1930년 창단}', $t$<p>상파울루는 브라질 최대 도시 상파울루를 대표하는 명문 구단입니다. 텔레 산타나 감독과 하이가 이끈 팀이 1992년과 1993년 코파 리베르타도레스와 인터콘티넨털컵을 연달아 들어 올렸고, 2005년에는 리베르타도레스와 클럽 월드컵을 함께 차지했습니다. 2006년부터 2008년까지 전국리그 3연패를 달성했으며, 프리킥과 페널티킥으로 100골 넘게 넣은 골키퍼 호제리우 세니가 구단의 상징입니다. 팔메이라스와의 "쇼키헤이"는 상파울루의 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 상파울루는 대형 홈구장 모룸비에서의 경기력이 시즌 성적을 좌우하는 경우가 많아 홈 경기당 승점을 먼저 보세요. 실점이 적은 시즌에 성적이 좋았던 전통이 있으니 무실점 비율도 함께 확인하면 좋습니다.</p>$t$),
(1772, '베르당 두 오에스치', '{샤페쿠,아레나 콘다,1973년 창단}', $t$<p>샤페코엔시는 산타카타리나주 서부의 도시 샤페쿠를 연고로 하는 구단입니다. 2009년 4부 리그에서 시작해 2014년 1부까지 올라온 기적 같은 성장으로 주목받았고, 2016년에는 코파 수다메리카나 결승에 진출했습니다. 그러나 결승 1차전을 치르러 콜롬비아 메데인으로 향하던 전세기가 2016년 11월 추락해 선수단과 관계자, 기자 등 71명이 목숨을 잃었습니다. 결승 상대였던 아틀레치쿠 나시오나우의 요청에 따라 남미축구연맹은 샤페코엔시에 대회 우승을 안겼고, 구단은 이후 팀을 다시 일으켜 세웠습니다.</p><p>토리코리 관전 포인트: 샤페코엔시는 전력이 강한 팀이 아니어서 홈에서 얼마나 승점을 쌓는지가 잔류의 관건이므로 홈 경기당 승점을 먼저 확인해 보세요. 실점을 줄이는 경기 운영을 하는 경우가 많아 무실점 비율과 2.5골 언더 경기 비율을 함께 보면 좋습니다.</p>$t$),
(1766, '갈루', '{벨루오리존치,아레나 MRV,1908년 창단}', $t$<p>아틀레치쿠 미네이루는 미나스제라이스주의 주도 벨루오리존치를 연고로 하는 구단으로, "수탉"이라는 뜻의 별명으로 불립니다. 1971년 첫 브라질 전국리그 우승을 차지했고, 2013년에는 호나우지뉴를 앞세워 코파 리베르타도레스 정상에 올랐습니다. 2021년에는 전국리그와 코파 두 브라질을 함께 차지했으며, 2023년 새 홈구장 아레나 MRV를 열었습니다. 같은 도시의 크루제이루와 치르는 클라시쿠 미네이루는 브라질에서 손꼽히는 라이벌전입니다.</p><p>토리코리 관전 포인트: 아틀레치쿠는 뜨거운 홈 응원을 등에 업고 홈에서 승점을 많이 쌓는 팀이라 홈·원정 경기당 승점의 차이를 눈여겨보세요. 컵 대회를 병행하는 시기에는 최근 5경기 성적이 흔들리는 경우가 있어 일정과 함께 보는 것이 좋습니다.</p>$t$),
(1768, '푸라캉', '{쿠리치바,아레나 다 바이샤다,1924년 창단}', $t$<p>아틀레치쿠 파라나엔시는 파라나주의 주도 쿠리치바를 연고로 하는 구단으로, "허리케인"이라는 뜻의 별명으로 불립니다. 2001년 브라질 전국리그 우승을 차지했고, 코파 수다메리카나에서 2018년과 2021년 두 차례 정상에 올랐으며 2019년에는 코파 두 브라질도 들어 올렸습니다. 홈구장 아레나 다 바이샤다는 2014년 월드컵 경기장으로 쓰였고, 개폐식 지붕과 인조 잔디를 갖춘 독특한 경기장입니다. 같은 도시의 코리치바와 치르는 아틀레치바 더비가 유명합니다.</p><p>토리코리 관전 포인트: 인조 잔디 홈구장에 익숙한 팀이라 홈 경기당 승점이 원정보다 크게 높은 경우가 많으니 두 지표를 꼭 나눠 보세요. 원정에서 실점이 늘어나는지 전반·후반 득실점과 함께 확인하면 팀의 약점을 읽기 쉽습니다.</p>$t$),
(6684, '콜로라두', '{포르투알레그리,베이하히우,1909년 창단}', $t$<p>인테르나시오나우는 포르투알레그리를 연고로 하는 구단으로, 빨간색 유니폼 때문에 "콜로라두"라는 별명으로 불립니다. 1970년대 파우카웅을 중심으로 전국리그를 세 차례 차지했고, 1979년에는 무패로 우승하는 기록을 남겼습니다. 2006년 코파 리베르타도레스 우승에 이어 같은 해 클럽 월드컵 결승에서 바르셀로나를 꺾었고, 2010년 두 번째 리베르타도레스 정상에 올랐습니다. 같은 도시의 그레미우와 치르는 그레나우 더비는 브라질 최고의 라이벌전으로 꼽힙니다.</p><p>토리코리 관전 포인트: 인테르나시오나우는 홈구장 베이하히우에서의 성적이 안정적인 편이라 홈 경기당 승점과 무실점 비율을 먼저 확인해 보세요. 그레나우 같은 라이벌전은 득점이 적게 나는 경우가 많아 2.5골 오버 비율과 따로 비교해 보는 것도 좋습니다.</p>$t$),
(4241, '코샤', '{쿠리치바,코우투 페헤이라,1909년 창단}', $t$<p>코리치바는 쿠리치바를 연고로 하는 구단으로, 독일계 이민자들이 만든 파라나주에서 가장 오래된 축구 구단 가운데 하나입니다. 초록색과 흰색 유니폼을 입으며, 팬들 사이에서는 "코샤"라는 짧은 별명으로 불립니다. 1985년 브라질 전국리그 우승이 구단 역사상 가장 큰 성과로 꼽힙니다. 같은 도시의 아틀레치쿠 파라나엔시와 치르는 아틀레치바 더비는 남부 지역의 대표 라이벌전입니다.</p><p>토리코리 관전 포인트: 1부와 2부를 오가는 시기가 잦았던 팀이라 경기당 승점으로 잔류 경쟁력을 먼저 가늠해 보세요. 브라질 리그는 달력 기준 한 해 동안 치러지므로 시즌 초반 성적과 최근 5경기 흐름을 비교하면 팀의 상승세를 확인하기 좋습니다.</p>$t$),
(1779, '치망', '{상파울루,네오 키미카 아레나,1910년 창단}', $t$<p>코린치앙스는 1910년 상파울루의 노동자들이 영국의 코린티안 구단에서 이름을 따 만든 구단으로, 브라질에서 두 번째로 많은 팬을 가진 팀으로 알려져 있습니다. 1980년대 소크라치스가 이끈 "코린치앙스 민주주의" 운동은 군사 정권 시절 브라질 사회에 큰 울림을 남겼습니다. 2000년 첫 클럽 월드컵 우승에 이어 2012년에는 코파 리베르타도레스와 클럽 월드컵을 함께 차지하며 결승에서 첼시를 꺾었습니다. 팔메이라스와 치르는 "더비 파울리스타"는 브라질에서 가장 뜨거운 경기 가운데 하나입니다.</p><p>토리코리 관전 포인트: 코린치앙스는 전통적으로 수비를 단단히 하는 경기가 많아 무실점 비율과 2.5골 언더 경기 비율이 팀 성향을 잘 보여 줍니다. 홈 관중의 압박이 큰 팀이라 홈·원정 경기당 승점 차이도 함께 확인해 보세요.</p>$t$),
(1771, '하포자', '{벨루오리존치,미네이랑,1921년 창단}', $t$<p>크루제이루는 벨루오리존치의 이탈리아 이민자들이 "팔레스트라 이탈리아"라는 이름으로 만든 구단으로, 1942년 지금의 이름으로 바뀌었습니다. 1976년과 1997년 코파 리베르타도레스를 차지했고, 2003년에는 전국리그와 코파 두 브라질, 주 리그를 모두 휩쓸었습니다. 토스탕이 1960년대 황금기를 이끌었고, 호나우두가 프로 무대에 데뷔한 구단이기도 합니다. 2019년 창단 후 처음 2부로 강등됐다가 2022년 2부 우승으로 1부에 복귀했으며, 아틀레치쿠 미네이루와의 클라시쿠 미네이루는 미나스제라이스주 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 크루제이루는 대형 경기장 미네이랑을 홈으로 쓰는 만큼 홈 경기당 승점이 시즌 성적의 바로미터입니다. 접전이 많은 팀이라 전반·후반 득실점을 비교해 승부가 주로 어느 시간대에 갈리는지 확인해 보세요.</p>$t$),
(1769, '베르당', '{상파울루,알리안츠 파르키,1914년 창단}', $t$<p>팔메이라스는 상파울루의 이탈리아 이민자들이 "팔레스트라 이탈리아"라는 이름으로 만든 구단으로, 1942년 지금의 이름으로 바뀌었습니다. 브라질 전국리그 최다 우승 구단으로 꼽히며, 코파 리베르타도레스는 1999년에 이어 2020년과 2021년 2연패를 달성했습니다. 아지미르 다 기아가 이끈 1960~70년대 "아카데미아" 시절은 구단의 대표적인 황금기입니다. 코린치앙스와의 더비 파울리스타, 상파울루와의 쇼키헤이가 모두 브라질을 대표하는 라이벌전입니다.</p><p>토리코리 관전 포인트: 팔메이라스는 꾸준히 상위권을 지키는 팀이라 경기당 승점과 함께 무실점 비율, 경기당 실점을 보면 강팀다운 안정감을 확인할 수 있습니다. 세트피스와 후반 득점이 많은 편인지 전반·후반 득실점 지표로 살펴보세요.</p>$t$),
(1783, '멩강', '{리우데자네이루,마라카낭,1895년 창단}', $t$<p>플라멩구는 1895년 리우데자네이루에서 조정 클럽으로 출발했고, 1911년 플루미넨시를 떠난 선수들이 합류하며 축구부를 만들었습니다. 브라질에서 가장 많은 팬을 가진 구단으로 꼽히며, 빨간색과 검은색 유니폼에서 "후브루네그루"라는 별명도 나왔습니다. 지쿠가 이끈 1981년 팀은 코파 리베르타도레스 우승에 이어 인터콘티넨털컵에서 리버풀을 꺾었고, 2019년과 2022년에도 리베르타도레스 정상에 올랐습니다. 플루미넨시와의 "플라-플루", 바스쿠와의 "백만 관중의 더비"가 유명합니다.</p><p>토리코리 관전 포인트: 플라멩구는 상대 진영에서 공을 오래 갖고 많은 골을 넣는 팀이라 경기당 득점과 2.5골 오버 비율이 높은지 먼저 확인해 보세요. 리그와 컵 대회를 함께 치르는 일정이 빡빡해 로테이션이 잦은 시기에는 최근 5경기 성적이 흔들릴 수 있습니다.</p>$t$),
(1765, '플루', '{리우데자네이루,마라카낭,1902년 창단}', $t$<p>플루미넨시는 1902년 리우데자네이루에서 오스카르 콕스가 중심이 되어 만든, 리우에서 가장 오래된 축구 구단 가운데 하나입니다. 적갈색·초록색·흰색의 삼색 유니폼 때문에 "트리콜로르"라고도 불리며, 마르셀루 같은 스타를 길러 낸 유소년 육성으로도 유명합니다. 2023년 결승에서 보카 주니어스를 꺾고 구단 첫 코파 리베르타도레스 우승을 차지했습니다. 플라멩구와 치르는 "플라-플루"는 마라카낭을 가득 채우는 브라질의 대표 더비입니다.</p><p>토리코리 관전 포인트: 플루미넨시는 짧은 패스로 점유율을 높이는 경기가 많아 득점보다 실점 지표, 특히 무실점 비율에서 팀 상태가 잘 드러납니다. 마라카낭을 함께 쓰는 만큼 홈 경기당 승점이 원정과 얼마나 차이 나는지도 확인해 보세요.</p>$t$),
(4287, '레앙 아줄', '{벨렝,바에낭,1905년 창단}', $t$<p>헤무는 아마존 하구의 도시이자 파라주의 주도인 벨렝을 연고로 하는 구단입니다. 이름처럼 조정 클럽에서 출발했으며, 짙은 파란색 유니폼 때문에 "파란 사자"라는 별명으로 불립니다. 브라질 북부 지역에서 가장 많은 팬을 가진 구단 가운데 하나로, 오랫동안 하위 전국리그에서 활동하면서도 큰 경기마다 많은 관중을 불러 모았습니다. 같은 도시의 파이산두와 치르는 "헤-파" 더비는 100년 넘게 이어져 온 아마존 지역 최대의 라이벌전입니다.</p><p>토리코리 관전 포인트: 적도 부근의 덥고 습한 벨렝에서 열리는 홈 경기는 원정팀에게 부담이 커서 홈·원정 경기당 승점 차이를 먼저 보는 것이 좋습니다. 1부 무대에 익숙하지 않은 팀이라 경기당 승점과 무실점 비율로 잔류 경쟁력을 가늠해 보세요.</p>$t$)
